        _ = build_config_mod.addImport("config.x.zig", config_x_mod);
        const build_tables_mod = b.createModule(.{ .root_source_file = b.path("src/build/tables.zig"), .target = b.graph.host, .optimize = build_tables_optimize });
        const build_tables_exe = b.addExecutable(.{ .name = "uucode_build_tables", .root_module = build_tables_mod, .use_llvm = true });
        _ = build_tables_mod.addImport("config.zig", config_mod);
        _ = build_tables_mod.addImport("build_config", build_config_mod);
        _ = build_tables_mod.addImport("types.zig", types_mod);
        const run_build_tables_exe = b.addRunArtifact(build_tables_exe);
        _ = run_build_tables_exe.setCwd(b.path(""));
        const tables_path = run_build_tables_exe.addOutputFileArg("tables.zig");
        return BuiltTables{ .tables = tables_path, .build_tables = build_tables_mod };
}

pub fn createLibMod(b: *std.Build, target: std.Build.ResolvedTarget, optimize: std.builtin.OptimizeMode, build_tables_optimize: std.builtin.OptimizeMode, tables_path_opt: ?std.Build.LazyPath, build_config_path: std.Build.LazyPath) LibMod {
        const config_mod = b.createModule(.{ .root_source_file = b.path("src/config.zig"), .target = target, .optimize = optimize });
        const types_mod = b.createModule(.{ .root_source_file = b.path("src/types.zig"), .target = target, .optimize = optimize });
        _ = types_mod.addImport("config.zig", config_mod);
        _ = config_mod.addImport("types.zig", types_mod);
        const config_x_mod = b.createModule(.{ .root_source_file = b.path("src/x/config.x.zig"), .target = target, .optimize = optimize });
        const types_x_mod = b.createModule(.{ .root_source_file = b.path("src/x/types.x.zig"), .target = target, .optimize = optimize });
        _ = types_x_mod.addImport("config.x.zig", config_x_mod);
        _ = config_x_mod.addImport("types.x.zig", types_x_mod);
        _ = config_x_mod.addImport("types.zig", types_mod);
        _ = config_x_mod.addImport("config.zig", config_mod);
        const build_config_mod = b.createModule(.{ .root_source_file = build_config_path, .target = target });
        _ = build_config_mod.addImport("types.zig", types_mod);
        _ = build_config_mod.addImport("config.zig", config_mod);
        _ = build_config_mod.addImport("types.x.zig", types_x_mod);
        _ = build_config_mod.addImport("config.x.zig", config_x_mod);
        var build_tables: ?*std.Build.Module = null;
        _ = &build_tables;
        const tables_path = ((tables_path_opt) orelse (blk: {
        const t = buildTables(b, build_config_path, build_tables_optimize);
        build_tables = t.build_tables;
        break :blk t.tables;
}));
        const tables_mod = b.createModule(.{ .root_source_file = tables_path, .target = target, .optimize = optimize });
        _ = tables_mod.addImport("types.zig", types_mod);
        _ = tables_mod.addImport("types.x.zig", types_x_mod);
        _ = tables_mod.addImport("config.zig", config_mod);
        _ = tables_mod.addImport("build_config", build_config_mod);
        const get_mod = b.createModule(.{ .root_source_file = b.path("src/get.zig"), .target = target, .optimize = optimize });
        _ = get_mod.addImport("types.zig", types_mod);
        _ = get_mod.addImport("tables", tables_mod);
        _ = types_mod.addImport("get.zig", get_mod);
        const lib_mod = b.createModule(.{ .root_source_file = b.path("src/root.zig"), .target = target, .optimize = optimize });
        _ = lib_mod.addImport("types.zig", types_mod);
        _ = lib_mod.addImport("config.zig", config_mod);
        _ = lib_mod.addImport("types.x.zig", types_x_mod);
        _ = lib_mod.addImport("tables", tables_mod);
        _ = lib_mod.addImport("get.zig", get_mod);
        return LibMod{ .lib = lib_mod, .build_tables = build_tables, .tables_path = tables_path };
}

pub fn testSimpleBuildConfigWithJustFieldsFields0() !void {
        const build_config = buildBuildConfig(std.testing.allocator, (&.{ "name", "is_emoji", "bidi_class" }), null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, .debug);
        defer {
        _ = std.testing.allocator.free(build_config);
        }
        errdefer {
